mapper.select:
select d.dept_id, d.parent_id, d.ancestors, d.dept_name, d.order_num, d.leader,
       d.phone, d.email, d.status, d.del_flag, d.create_by, d.create_time,
       d.update_by, d.update_time
  from sys_dept d
 where d.shop_code = #{shopCode}
   and d.del_flag = '0'

   and d.dept_id = #{dept.deptId}


   and d.parent_id = #{dept.parentId}


   and d.dept_name like concat('%', #{dept.deptName}, '%')


   and d.status = #{dept.status}

 order by d.parent_id, d.order_num, d.dept_id

select s.shop_code, s.shop_name, s.status as shop_status, d.dept_id, d.parent_id, d.ancestors, d.dept_name, d.order_num, d.leader, d.phone, d.email, d.status, d.create_time, (select count(1) from sys_shop_user su where su.shop_code = d.shop_code and su.dept_id = d.dept_id and su.del_flag = '0') as employee_count from s_m_shop s join sys_dept d on d.shop_code = s.shop_code and d.del_flag = '0' where s.status <> -1
and s.shop_code = #{query.shopCode}
and d.dept_name like concat('%', #{query.deptName}, '%')
and d.status = #{query.status}
order by s.createtime, s.shop_code, d.parent_id, d.order_num, d.dept_id

select count(1)
  from sys_dept
 where shop_code = #{shopCode}
   and parent_id = #{parentId}
   and dept_name = #{deptName}
   and del_flag = '0'

   and dept_id != #{excludeDeptId}

mapper.update:
update sys_dept
   set ancestors = case dept_id

       when #{item.deptId} then #{item.ancestors}

       end
 where shop_code = #{shopCode}
   and dept_id in

    #{item.deptId}

mapper.select:
select count(1) from sys_shop_user
 where shop_code = #{shopCode} and user_code = #{userCode}
   and del_flag = '0' and status = '0'

select count(1) from sys_shop_user
 where shop_code = #{shopCode} and job_no = #{jobNo} and del_flag = '0'

   and user_code != #{excludeUserCode}

mapper.delete:
delete sur from sys_shop_user_role sur
inner join sys_shop_user su on su.shop_code = sur.shop_code and su.user_code = sur.user_code
 where sur.shop_code = #{shopCode} and sur.user_code = #{userCode}

mapper.select:
select r.role_code, r.shop_code, r.role_name, r.role_key, r.role_sort, r.data_scope, r.menu_check_strictly, r.dept_check_strictly, r.status, r.del_flag, r.role_type, r.system_flag, r.create_by, r.create_time, r.update_by, r.update_time, r.remark from sys_role r where r.shop_code = #{shopCode} and r.role_type = 'TENANT' and r.del_flag = '0'
and r.role_code = #{role.roleCode}
and r.role_name like concat('%', #{role.roleName}, '%')
and r.role_key like concat('%', #{role.roleKey}, '%')
and r.status = #{role.status}
order by r.system_flag desc, r.role_sort, r.role_code

select count(1) from sys_shop_user_role sur
join sys_shop_user su on su.shop_code = sur.shop_code and su.user_code = sur.user_code and su.del_flag = '0'
 where sur.shop_code = #{shopCode} and sur.role_code = #{roleCode}

mapper.update:
update sys_role set del_flag = '2', update_by = #{updateBy}, update_time = sysdate()
 where shop_code = #{shopCode} and role_code = #{roleCode}
   and role_type = 'TENANT' and system_flag = 0 and del_flag = '0'

mapper.insert:
insert into sys_role_menu(role_code, fun_code) select r.role_code, requested.fun_code from sys_role r join (
select #{funCode} as fun_code
) requested where r.shop_code = #{shopCode} and r.role_type = 'TENANT' and (r.system_flag = 0 or #{includeSystem} = true) and r.role_code = #{roleCode}

mapper.select:
select fun_code, menu_name, parent_id, order_num, path, component, `query`, route_name, is_frame, is_cache, menu_type, visible, status, ifnull(perms, '') as perms, icon from sys_menu where status = '0' and fun_code in
#{funCode}
order by parent_id, order_num
